<section class="hero"><div class="eyebrow">AfiuCMS</div><h1><?= e($settings['site_name']??'AfiuCMS Site') ?></h1><p><?= e($settings['site_tagline']??'') ?></p><div class="hero-actions"><a href="/blog">Explore stories</a><a class="secondary" href="/search">Search</a></div></section><section class="section"><div class="section-head"><div><span>Latest</span><h2>Recent posts</h2></div><a href="/blog">View all →</a></div><div class="posts"><?php foreach($posts as $post):?><article class="post-card"><?php if(!empty($post['featured_media_id'])):?><img src="/media/<?= (int)$post['featured_media_id'] ?>" alt=""><?php endif;?><div class="post-inner"><div class="date"><?= e(substr((string)$post['published_at'],0,10)) ?></div><h3><a href="/blog/<?= e($post['slug']) ?>"><?= e($post['title']) ?></a></h3><p><?= e($post['excerpt']?:'Open the post to continue reading.') ?></p></div></article><?php endforeach;?><?php if(!$posts):?><div class="empty">Your site is ready. Publish your first post from AfiuCMS.</div><?php endif;?></div></section>